import type {Exercise,Lesson,Track} from './types';
type Question=NonNullable<Exercise['quiz']>[number];
const q=(question:string,options:string[],answer:number,explanation:string):Question=>({question,options,answer,explanation});
type Topic={id:string;example:string;pitfall:string;deliverable:string;questions:Question[];practice?:string};
const topics:Topic[]=[
{id:'digital',example:'An alarm is active when enable AND (overheat OR overcurrent). Enumerate all eight input combinations. With enable=0, the alarm is always 0. With enable=1, only overheat=0 and overcurrent=0 produces 0. This becomes alarm = enable & (overheat | overcurrent).',pitfall:'Confusing logical negation with bitwise inversion on a vector; simplifying an expression without checking its full truth table.',deliverable:'A truth table, a simplified expression and an explanation of why they are equivalent.',questions:[q('For y = a&b | a&~b, the simplified output is…',['a','b','a^b'],0,'Factor a and use b | ~b = 1.'),q('What is a valid proof for two 3-input Boolean expressions?',['One random example','Compare all 8 input combinations','Compare source line counts'],1,'Exhaustive truth tables cover all possible inputs.'),q('If enable=0 in enable & (hot | current), the output is…',['Always 0','Always 1','Previous output'],0,'A combinational AND with 0 is 0, without state.')],practice:'mux2'},
{id:'numbers',example:'For 4-bit two’s complement, 0111 is +7 and 1000 is −8. Adding 0111 + 0001 gives 1000: unsigned 8 is representable, but signed +8 is not. Overflow is detected when equal-sign operands produce a result of the opposite sign.',pitfall:'Treating a carry-out bit as signed overflow, or extending a signed quantity with zeros instead of its sign bit.',deliverable:'Convert 0xE to signed and unsigned decimal, sign-extend it to 8 bits, and explain the overflow case 7+1.',questions:[q('4-bit 1110 interpreted as two’s complement equals…',['14','−2','−6'],1,'Invert 1110 to 0001 and add one to get magnitude 2.'),q('Sign-extending 4-bit 1010 to 8 bits gives…',['00001010','11111010','10100000'],1,'Repeat the original sign bit, preserving −6.'),q('4-bit signed 7+1 produces…',['No overflow because carry is zero','Signed overflow','A fifth sign bit automatically'],1,'The signed range ends at +7.')],practice:'full-adder'},
{id:'combinational',example:'A 3-to-8 decoder implements y = 1 << address when enabled. With enable=0 all eight outputs are zero. Only one output is asserted for every legal address. Exhaustive testing requires 8 enabled cases plus disabled behavior.',pitfall:'Missing a default assignment, using a priority chain where parallel decoding was intended, and not checking multi-active encoder inputs.',deliverable:'A decoder truth table and an exhaustive self-checking test.',questions:[q('How many address combinations must a 3-input decoder cover?',['3','8','16'],1,'Three bits produce 2³ combinations.'),q('A priority encoder must define behavior when…',['Several inputs are asserted','The source file is renamed','The clock is disabled'],0,'Priority resolves multiple simultaneous active inputs.'),q('Combinational code with an unassigned output branch may infer…',['A latch','A faster adder','A clock divider'],0,'The previous value must be retained on the missing branch.')],practice:'priority-encoder'},
{id:'sequential',example:'Consider two registers a and b updated by a<=in; b<=a at a rising edge. b receives the old a, so a change on in reaches b after two sampling edges. Replacing both statements with blocking assignments can incorrectly collapse that behavior in simulation.',pitfall:'Assuming procedural statement order creates a physical pipeline, or forgetting to specify reset versus enable priority.',deliverable:'A cycle table containing reset, enable, input and each register value before and after the edge.',questions:[q('For a<=in; b<=a in a clocked block, b receives…',['The old a','The new in immediately','An unknown value in every case'],0,'Nonblocking right-hand sides are evaluated before updates are applied.'),q('A latch is normally…',['Edge-triggered','Level-sensitive','Combinational with no state'],1,'It is transparent while its enable level is active.'),q('Which test best checks reset priority?',['Reset=1 and enable=1 together','Enable=0 forever','Only initialize simulation variables'],0,'Competing controls expose the priority rule.')],practice:'sync-register'},
{id:'fsm-theory',example:'For an overlapping 1011 detector, encode matched prefixes: none, 1, 10 and 101. From 101 with input 1, report a match and retain prefix 1, because that final bit can begin the next sequence. The stream 1011011 contains two matches.',pitfall:'Returning to the empty state after every match and thereby losing overlapping detections.',deliverable:'A state-transition table with every state/input pair, a reset state and an overlap trace.',questions:[q('After matching 1011, an overlapping detector should retain…',['Prefix 1','Prefix 10','No prefix in all designs'],0,'The last 1 is also a valid first bit.'),q('A Moore output depends on…',['State only','Current input only','Filename and seed'],0,'A Mealy output depends on both state and input.'),q('A complete 4-state binary-input transition table contains…',['4 cases','8 cases','16 clock sources'],1,'Each state has two input possibilities.')],practice:'fsm'},
{id:'architecture',example:'In a five-stage pipeline, ADD x3,x1,x2 followed by SUB x4,x3,x5 creates a read-after-write dependency. Forwarding can provide the ADD result before register writeback. A load-use dependency may still need a stall if memory data is unavailable in time.',pitfall:'Describing a hazard as merely a performance issue while allowing the consuming instruction to use stale data.',deliverable:'A pipeline timing diagram for an ALU dependency and a load-use dependency, including the selected resolution.',questions:[q('A RAW hazard occurs when a later instruction…',['Reads a value an earlier instruction has not produced yet','Writes an unrelated register','Uses a different opcode'],0,'The consumer needs a pending producer result.'),q('Which item is architectural state?',['Program-visible registers','A simulator progress bar','The RTL indentation'],0,'Architectural state determines the software-visible machine.'),q('Forwarding mainly addresses…',['Data dependencies','Clock skew closure','Source-control conflicts'],0,'It bypasses pending results to consumers.')],practice:'alu4'},
{id:'linux',example:'A regression command can succeed in starting the simulator yet fail its tests. Capture the simulator exit status, keep stdout/stderr, and make the outer script exit nonzero on a failure. Use a fresh output directory for each run to avoid stale PASS logs.',pitfall:'Reusing an old result file after a failed command, or ignoring an exit code because a log file exists.',deliverable:'A directory tree for rtl/, tb/, scripts/, results/ and a README describing commands and exit codes.',questions:[q('Which exit status convention normally indicates success?',['0','1','Any positive integer'],0,'Zero signals successful completion by convention.'),q('What should a regression do after a compile failure?',['Run a stale executable','Stop and report infrastructure/compile failure','Mark the test Passed'],1,'Running an old binary does not test the submitted source.'),q('Which path is relative?',['rtl/counter.v','/home/user/counter.v','C:\\rtl\\counter.v'],0,'Its meaning depends on the current working directory.')]},
{id:'git',example:'A useful commit changes one behavior: fix reset priority, add a regression reproducer, and update the expected result. The README records exact tool commands. Generated waveforms can be linked as evidence without committing every large build artifact.',pitfall:'Committing credentials, describing an unrun test as passed, and creating a repository that cannot be reproduced from its instructions.',deliverable:'A commit message, a .gitignore and reproducible README steps for one engineering change.',questions:[q('Before committing, which action best checks the intended change?',['Inspect the staged diff','Count repository stars','Rename every file'],0,'The staged diff is the actual snapshot to be committed.'),q('A repository should normally exclude…',['API secrets and generated build files','All testbenches','The README'],0,'Secrets must not be published; build outputs are usually reproducible.'),q('A reproducible README includes…',['Tool versions and exact run commands','Only a screenshot','Only the project title'],0,'A reviewer must be able to repeat the experiment.')]},
{id:'verilog',example:'A parameter WIDTH controls elaborated hardware structure. A WIDTH-bit input and output must be declared consistently. For a simple mux, assign y = sel ? b : a; describes combinational selection, not a software branch that executes only once.',pitfall:'Implicit nets caused by misspelled identifiers, and unexpected truncation from mixing expression widths.',deliverable:'A module with explicit ports, widths, parameters and a test demonstrating both selection branches.',questions:[q('A parameter normally controls…',['Elaboration-time structure','A value sampled on every clock edge','The browser theme'],0,'Changing parameters elaborates a different module instance.'),q('Assigning an 8-bit value to a 4-bit output normally…',['Truncates high bits','Allocates 8 bits automatically','Always raises a runtime exception'],0,'Width mismatches may silently discard bits.'),q('A continuous assignment models…',['A continuously driven combinational expression','A one-time initialization only','An operating-system thread'],0,'Its output is updated when its inputs change.')],practice:'mux2'},
{id:'comb-rtl',example:'Start an always @(*) block with y=0; then override it when en is true. This defines the disabled case and removes unintended state. Verify en=1→0 transitions; testing only stable en=1 would not expose the original latch.',pitfall:'Adding a clock to fix a latch warning when the specification requires combinational logic.',deliverable:'Corrected RTL and a test that enables the output, then disables it and checks the required default.',questions:[q('The safest place for combinational defaults is…',['At the start of the combinational block','Only in an initial block','Only at reset'],0,'Defaults provide a value for every path.'),q('always @(*) sensitivity is intended to include…',['All values read by the block','Only clk','Only values on the left-hand side'],0,'It reschedules the process when dependencies change.'),q('A latch fix should preserve…',['The intended combinational specification','The accidentally stored value','Only line count'],0,'Removing a warning is not enough if behavior changes incorrectly.')],practice:'latch'},
{id:'seq-rtl',example:'An enabled synchronous counter uses if(rst) count<=0; else if(en) count<=count+1. Reset therefore wins when both are asserted. For WIDTH=1, every enabled non-reset edge toggles the counter: this is an important parameter boundary.',pitfall:'Assuming a synchronous reset takes effect between edges, and failing to check wrap-around or WIDTH=1.',deliverable:'A reset-priority test, enable-hold test and rollover test at two legal widths.',questions:[q('A synchronous reset changes register state…',['On the active clock edge','Immediately on its own transition','Only during synthesis'],0,'Reset is sampled by the clocked block.'),q('With reset first in an if/else chain, reset and enable together produce…',['The reset state','An increment','Unspecified priority'],0,'The first matching branch defines priority.'),q('A WIDTH-bit ordinary binary counter wraps modulo…',['2^WIDTH','WIDTH','WIDTH+1'],0,'The fixed-width result discards carry-out.')],practice:'counter'},
{id:'fsm-rtl',example:'Keep state<=next_state in the sequential block. In combinational logic, set next_state=state and outputs to defaults before a case statement. Define behavior for invalid encodings; then exercise reset from each reachable state.',pitfall:'Omitting a next_state assignment or mixing old-state and new-state assumptions in testbench sampling.',deliverable:'A two-process FSM with an overlap trace, a reset trace and stated output timing.',questions:[q('A useful default for next_state is often…',['The current state','A random value','An uninitialized register'],0,'It gives explicit hold behavior before transition overrides.'),q('An invalid-state recovery branch should be…',['Defined and reviewed','Assumed unnecessary in every design','Placed only in the README'],0,'It makes intended recovery behavior explicit.'),q('The testbench must sample outputs according to…',['The specified clocking/output timing','The number of source lines','The IDE theme'],0,'Race-free sampling depends on the interface timing.')],practice:'fsm'},
{id:'simulation',example:'Compile the DUT and testbench together, elaborate the selected top, run the resulting simulation, and inspect its exit code. A $fatal check must fail the run. VCD records observed transitions and helps locate a divergence; it is not a correctness proof by itself.',pitfall:'Treating “no syntax errors” as a passing verification result, or simulating the wrong top module.',deliverable:'The source revision, compile command, simulation command, real log and a short waveform explanation.',questions:[q('Compilation without errors proves…',['The design is correct','Only that this compilation step succeeded','All coverage goals were reached'],1,'Behavioral correctness needs tests or formal properties.'),q('Why explicitly select a top module?',['To elaborate the intended testbench hierarchy','To change reset polarity','To enable GitHub sync'],0,'Unexpected roots can create unrelated or empty simulations.'),q('An FPGA timing report is needed because…',['RTL functional simulation does not establish physical timing closure','All simulated designs meet timing','Clock constraints are optional in hardware'],0,'Implementation delays and constraints need separate analysis.')],practice:'sync-register'},
{id:'python',example:'For each stripped log line, split into tokens and accept exactly PASS name or FAIL name. Comments and malformed lines must not change counts. A line containing the sentence “expected PASS but failed” is not a valid PASS record.',pitfall:'Counting substring matches and accidentally treating comments or diagnostics as test results.',deliverable:'A pure parser function and tests for empty input, valid records and malformed records.',questions:[q('Why use a pure function for a log summary?',['It is easier to test with controlled inputs','It bypasses all errors','It removes the need for specifications'],0,'Explicit inputs and return values make behavior reproducible.'),q('For malformed input, behavior should be…',['Specified and tested','Always silently count as Passed','Different on every run'],0,'Ignore, reject or report consistently according to the contract.'),q('Which input is an important parser boundary?',['An empty list','Only a large successful log','Only the default filename'],0,'Empty data often exposes initialization assumptions.')],practice:'python-log'},
{id:'python-oop',example:'A scoreboard owns an expected queue. The monitor reports observed bytes; the scoreboard removes and compares the oldest expected byte. Reset clears pending expectations according to the specification. The driver does not decide whether an observation passed.',pitfall:'Sharing one mutable list between independent scoreboards, or comparing against the DUT’s own internal calculation.',deliverable:'An object diagram for driver, monitor and scoreboard, with ownership and reset behavior.',questions:[q('Expected transactions for in-order comparison fit naturally in…',['A queue','A random integer','A GUI label'],0,'A queue preserves arrival order.'),q('Mutable per-instance data belongs…',['On the instance, initialized for each object','In a shared class list unless intended','In the module filename'],0,'Shared mutable defaults can leak state across test cases.'),q('A monitor should primarily…',['Observe accepted DUT transactions','Copy every driver request as successful','Repair the DUT output'],0,'Requests and accepted transfers can differ under backpressure.')],practice:'py-scoreboard'},
{id:'automation',example:'A regression result contains test name, source revision, seed, tool version, exit status and log path. A harness timeout is classified separately from a functional mismatch. Sorting discovered test files gives deterministic ordering.',pitfall:'Rerunning a failing random test without retaining its seed or confusing infrastructure failure with a learner’s failed assertion.',deliverable:'A structured result record and a bounded polling function with explicit timeout behavior.',questions:[q('A reproducible random failure requires retaining…',['The seed and source/tool context','Only wall-clock time','Only a screenshot of the editor'],0,'The same seed and implementation context are needed to reproduce it.'),q('A crashed simulator should be classified as…',['An infrastructure/execution error unless a functional failure was established','A passing test','100% coverage'],0,'No completed evaluation means no correctness result.'),q('Every wait in an automated harness should have…',['A meaningful timeout','An infinite loop','A random sleep only'],0,'Bounded waits prevent a stalled DUT from hanging the regression.')],practice:'py-timeout'},
{id:'cpp',example:'Use uint32_t for an explicitly unsigned 32-bit architectural model. Addition is modulo 2^32. Signed overflow in C++ is not interchangeable with modular unsigned arithmetic. Test 0xffffffff + 1 and document how narrower hardware fields are masked.',pitfall:'Relying on signed overflow, dereferencing invalid pointers or assuming int has the intended hardware width.',deliverable:'A type/width table and boundary vectors shared between an RTL function and a software model.',questions:[q('For portable 32-bit unsigned arithmetic, choose…',['uint32_t','Any pointer','A signed int without checking width'],0,'Fixed-width unsigned types state width and wrap semantics.'),q('A pointer and its pointee have…',['Different meanings: address/reference versus stored value','Always identical values','No lifetime considerations'],0,'Validity depends on the lifetime of the referenced object.'),q('C++ signed overflow is…',['A safe substitute for hardware wrap-around','Undefined behavior in ordinary arithmetic','Always saturation'],1,'Use unsigned arithmetic or explicitly checked operations.')]},
{id:'methodology',example:'For a FIFO requirement “read order equals accepted write order,” map stimulus to accepted write/read handshakes, a reference queue check, and coverage for empty/full transitions. Testing only random data values misses ordering and boundary requirements.',pitfall:'Using coverage percentage as a substitute for a checker, or deriving the expected output from the DUT implementation.',deliverable:'A requirement → stimulus → checker → coverage matrix with at least one negative test.',questions:[q('A test plan should link each requirement to…',['Stimulus, a checker and coverage','Only a filename','Only a project deadline'],0,'All three are needed to exercise, assess and measure the requirement.'),q('High functional coverage alone establishes…',['That specified scenarios were observed, not that all results were correct','Proof of no bugs','A passing scoreboard automatically'],0,'Coverage measures occurrence while checkers assess correctness.'),q('An independent reference model should be derived from…',['The specification','The DUT output copied verbatim','A passing screenshot'],0,'Independence helps catch implementation errors.')],practice:'py-scoreboard'},
{id:'sv',example:'An interface groups a bus’s signals. A modport gives a view with intended directions. A transaction class describes data rather than physical wires. Tasks may wait for time; a function must not suspend simulation with timing controls.',pitfall:'Mixing transaction objects and pin-level signals, or creating races by driving and sampling in the same scheduler region.',deliverable:'A bus signal table, driver/monitor direction views and a documented sampling policy.',questions:[q('An interface is used to…',['Bundle related signals and behavior','Automatically prove a protocol','Replace every transaction class'],0,'It organizes pin-level communication; correctness still needs checks.'),q('Which routine may contain timing controls?',['A task','An ordinary function','Both without restrictions'],0,'Tasks can suspend; functions must complete without timing controls.'),q('A modport primarily describes…',['Signal access/direction views','A random seed','A coverage percentage'],0,'It constrains how a component sees an interface.')]},
{id:'assertions',example:'For a request that requires a grant on the next clock, req |=> grant captures a one-cycle sampled implication. Also cover a request occurring; otherwise an idle design may pass vacuously. Reset disabling must match the requirement rather than hiding failures.',pitfall:'Confusing same-cycle |-> with next-cycle |=>, or reporting vacuous implication success as exercised behavior.',deliverable:'One correctness property, a corresponding activation cover and a failing trace.',questions:[q('Non-overlapping req |=> grant checks grant…',['At the next sampled clock','Only at elaboration','Always in the same sample'],0,'Non-overlapping implication advances the consequent to the next sample.'),q('A property can pass vacuously if…',['Its antecedent never occurs','Its consequent is false after a trigger','Every assertion is disabled by source comments'],0,'Use coverage to demonstrate activation.'),q('disable iff reset should reflect…',['The specification’s reset exclusion','A desire to improve pass rates','The current UI theme'],0,'Reset exclusions must be technically justified.')]},
{id:'random',example:'Generate legal FIFO writes and reads with a reproducible seed. The monitor updates the reference queue only when the transfer is accepted. Retain the shortest failing transaction sequence and the seed so the bug can become a directed regression.',pitfall:'Treating a requested transfer as accepted when the DUT is full or not ready.',deliverable:'A constrained stimulus policy and an in-order transaction checker with missing/extra data detection.',questions:[q('A monitor should enqueue data when…',['A write is accepted','A write is merely requested','The simulation ends'],0,'Only accepted transfers alter the reference state.'),q('Constrained random stimulus should primarily produce…',['Legal transactions plus intentional negative scenarios','Unspecified invalid values only','No repeatable seed'],0,'Legality and negative testing should be deliberate.'),q('A scoreboard must detect…',['Missing and extra transactions as well as mismatched values','Only the first correct byte','Only source formatting'],0,'Correctness includes sequence length and order.')],practice:'py-scoreboard'},
{id:'uvm',example:'A UVM agent contains a sequencer, driver and monitor for an interface. The scoreboard consumes observed transactions. Coverage closure reviews unhit bins and exclusions, then adds targeted stimulus. A reusable environment separates protocol components from a particular test.',pitfall:'Adding UVM classes without a checking strategy, and claiming closure by deleting difficult bins without justification.',deliverable:'A component diagram, a sequence-to-driver flow and a coverage-closure review with explicit exclusions.',questions:[q('A UVM monitor normally publishes…',['Observed transactions','The final synthesized netlist','Only random constraints'],0,'Analysis communication carries observations to checkers and coverage collectors.'),q('An unhit coverage goal should first be…',['Reviewed against requirements and stimulus reachability','Deleted automatically','Marked covered manually'],0,'Determine whether stimulus, checking or the goal itself needs correction.'),q('A reusable agent should isolate…',['Protocol-specific driving and monitoring','A single user’s CV','All verification results from requirements'],0,'Separating protocol components supports reuse across environments.')]},
{id:'uart-lesson',example:'An 8N1 frame is [start=0, d0…d7, stop=1]. For byte 0xA5 the data bits are 1,0,1,0,0,1,0,1. Verify framing before reconstructing the byte. A production receiver also needs timing, baud tolerance and reset tests.',pitfall:'Reconstructing data MSB-first, accepting a low stop bit or forgetting to define sampling timing.',deliverable:'A frame decoder with positive and malformed-frame tests, followed by a receiver timing test plan.',questions:[q('UART 8N1 data bits are typically sent…',['Least-significant bit first','Most-significant bit first','In alphabetical order'],0,'8N1 convention sends d0 before d7.'),q('A valid idle/stop level in ordinary UART is…',['High','Low','Always high impedance'],0,'Start is low and the stop interval returns high.'),q('A byte-level decoder alone does not verify…',['Baud timing and sample-point robustness','The arithmetic value of a supplied frame','Bit order in supplied data'],0,'Pin-level timing needs a separate receiver simulation.')],practice:'py-uart'},
{id:'fifo-lesson',example:'At occupancy 0, a read request may be rejected; at occupancy depth, a write may be rejected. Update a reference queue only after applying the exact acceptance policy. At full with simultaneous read/write, behavior must be specified rather than guessed.',pitfall:'Assuming synchronous FIFO tests establish asynchronous CDC safety, and ignoring pointer wrap-around.',deliverable:'A boundary matrix covering empty, one item, nearly full, full, wrap and simultaneous operations.',questions:[q('FIFO reference occupancy changes on…',['Accepted operations','Every request regardless of acceptance','Clock edges only when the UI is open'],0,'The acceptance contract determines state changes.'),q('For an asynchronous FIFO, verification also needs…',['CDC/reset assumptions and crossing analysis','Only a synchronous queue test','Only random data values'],0,'Different clock domains introduce separate correctness concerns.'),q('At full with read and write together, the expected behavior is…',['Whatever the documented interface policy specifies','Universally identical for all FIFOs','Always an error in every design'],0,'Acceptance and flag timing vary and must be explicit.')],practice:'py-scoreboard'},
{id:'apb-lesson',example:'An APB transfer enters setup with PSEL=1,PENABLE=0, then access with PENABLE=1. It completes when PSEL && PENABLE && PREADY. During waits, address/control stay stable. A byte-strobe model updates only selected register bytes where the applicable APB version supports strobes.',pitfall:'Sampling data on setup rather than completion, or applying an APB4 strobe assumption to an APB3-only design.',deliverable:'A two-phase transfer trace with wait states and a register update model with documented protocol version.',questions:[q('An APB transfer completes when…',['PSEL && PENABLE && PREADY','PSEL alone','PENABLE=0'],0,'The access handshake defines acceptance.'),q('During access wait states, address/control should…',['Remain stable','Randomize every cycle','Match the browser clock'],0,'They belong to one pending transaction.'),q('Before writing a checker, specify…',['The protocol version and supported features','Only the module filename','Only how many tests you want'],0,'Optional/versioned signals change the checking contract.')],practice:'py-mask'},
{id:'riscv',example:'For a selected RV32I subset, compare retired instructions to a reference model: PC, instruction, destination register and memory effects. Register x0 remains zero. Branch tests must include taken/not-taken paths and immediate sign extension; integration adds interrupts and memory-map assumptions.',pitfall:'Checking only final register state while missing wrong intermediate retirement or memory side effects.',deliverable:'A retirement comparison record and an ISA test matrix including illegal/unsupported cases.',questions:[q('RV32I register x0 reads as…',['Zero','The previous ALU result','An arbitrary reset value'],0,'x0 is hardwired to zero architecturally.'),q('Differential checking should compare…',['Architectural retirement effects','Only RTL source length','Only total simulation time'],0,'Architectural observations support implementation-independent comparison.'),q('Before calling a processor verified, document…',['ISA subset, memory model and excluded features','Only the test count','Only the simulator brand'],0,'Results are meaningful only within an explicit scope.')]}
];

const executable=(id:string,title:string,track:Track,language:Exercise['language'],description:string,starter:string,specs:string[],tests:string[],solution:string):Exercise=>({id,title,track,language,description,starter,specs,tests,solution,difficulty:track==='Advanced Applications'?'Advanced':'Intermediate',kind:'Coding',minutes:35,objectives:['Implement the precise interface contract','Validate normal, boundary and invalid cases with real execution'],hints:['Write a simple reference example before implementation.','Handle reset, empty input or boundary values before the normal path.']});
export const codingExercises:Exercise[]=[
executable('mux2','Combinational 2:1 multiplexer','RTL Design','verilog','Select between two single-bit inputs. Verify all eight combinations, including both select transitions.','module mux2(input wire a,b,sel, output wire y);\n // Implement y.\nendmodule',['y=a when sel=0; y=b when sel=1.','No state or clock.'],['All a/b/sel combinations.','Changing the unselected input must not alter y.'],'Use a continuous conditional assignment. Enumerating all eight input combinations is exhaustive.'),
executable('decoder3','Enabled 3-to-8 decoder','Foundation','verilog','Produce exactly one active output for a 3-bit address, or all zeros when disabled.','module decoder3(input wire [2:0] address, input wire en, output wire [7:0] y);\n // Decode address when enabled.\nendmodule',['y=0 when en=0.','When enabled, y[address]=1 and all other bits are 0.'],['Disabled for every address.','All eight enabled addresses.'],'Use an explicitly 8-bit one shifted by address and gate it with enable.'),
executable('full-adder','Full adder with carry','Foundation','verilog','Implement a one-bit full adder and distinguish its sum bit from carry-out.','module full_adder(input wire a,b,cin, output wire sum,cout);\n // Implement both outputs.\nendmodule',['sum is the low bit of a+b+cin.','cout is the high bit.'],['All eight input combinations.','Three asserted inputs gives sum=1, cout=1.'],'sum=a^b^cin; cout=(a&b)|(a&cin)|(b&cin). Check both bits of the reference sum.'),
executable('alu4','4-bit ALU operation decode','RTL Design','verilog','Implement a small combinational ALU with fixed-width arithmetic.','module alu4(input wire [3:0] a,b, input wire [1:0] op, output reg [3:0] y);\n always @(*) begin\n  // 0:add, 1:subtract, 2:AND, 3:XOR\n end\nendmodule',['op 0 add, 1 subtract, 2 AND, 3 XOR.','Arithmetic wraps modulo 16; y assigned on every path.'],['All 16×16×4 combinations.','Addition overflow and subtraction underflow.'],'Use a complete case statement and 4-bit output truncation. A reference model masks arithmetic results with 15.'),
executable('edge-detector','Synchronous rising-edge pulse','RTL Design','verilog','Create a one-cycle pulse when the sampled input rises from 0 to 1.','module edge_detector(input wire clk,rst,din, output reg pulse);\n // Save the previous sampled input.\nendmodule',['Synchronous active-high reset clears previous input and pulse.','At each non-reset rising edge, pulse=din & ~previous_din.'],['A held high input produces only one pulse.','Reset while high then release.','Alternating and repeated input levels.'],'Store the previous sample and use nonblocking assignments. Specify reset behavior for both state and output.'),
executable('shift-register','Enabled 4-bit shift register','RTL Design','verilog','Shift incoming bits into a fixed-width register while preserving enable and reset priorities.','module shift_register(input wire clk,rst,en,din, output reg [3:0] q);\n // Shift toward bit 3; insert din at bit 0.\nendmodule',['Reset synchronously clears q and overrides en.','When enabled q becomes {q[2:0],din}; otherwise hold.'],['Reset, disabled hold, multiple serial patterns.','Bits shift out after four enabled edges.'],'Use q <= {q[2:0], din} in the enabled branch of a clocked block.'),
executable('saturating-counter','4-bit saturating counter','RTL Design','verilog','Unlike a wrapping counter, this counter must stop at the maximum value.','module saturating_counter(input wire clk,rst,en, output reg [3:0] count);\n // Saturate at 15.\nendmodule',['Reset overrides enable.','Increment only when en and count<15.','Hold at 15 until reset.'],['More than 20 enabled edges.','Disable before maximum and reset at maximum.'],'Guard increment with count != 4\'hf; ordinary overflow would incorrectly wrap to zero.'),
executable('parity8','Even-parity bit for a byte','Foundation','verilog','Generate the bit that makes the total number of ones even.','module parity8(input wire [7:0] data, output wire parity);\n // One parity bit.\nendmodule',['data concatenated with parity has even one-count.'],['All 256 bytes.','Zero, all ones and one-hot values.'],'The reduction XOR of the eight data bits is the required even-parity bit.'),
executable('comparator4','Unsigned 4-bit comparator','Foundation','verilog','Produce mutually exclusive less-than, equal and greater-than flags.','module comparator4(input wire [3:0] a,b, output wire lt,eq,gt);\n // Unsigned comparisons.\nendmodule',['Exactly one flag must be 1 for each input pair.','Inputs are unsigned.'],['All 256 input pairs.','Equality and values 8–15.'],'Use explicit unsigned vector comparisons. Values with a high sign bit must still be interpreted as unsigned.'),
executable('sync-register','Enabled register with reset priority','RTL Design','verilog','Implement one 8-bit register and test simultaneous reset/enable assertions.','module sync_register(input wire clk,rst,en, input wire [7:0] d, output reg [7:0] q);\n // Synchronous register.\nendmodule',['Synchronous active-high reset clears q.','Enable captures d; otherwise q holds.','Reset wins over enable.'],['Capture multiple patterns.','Change d while disabled.','Assert reset and enable together.'],'Use if(rst) q<=0; else if(en) q<=d in always @(posedge clk).'),
executable('py-scoreboard','In-order transaction scoreboard','Design Verification','python','Compare complete expected and actual transaction sequences, including missing and extra transactions.','def compare_transactions(expected, actual):\n    # Return a list of mismatch dictionaries.\n    return []\n',['Return a list of {"index": i, "expected": value_or_None, "actual": value_or_None}.','Include every differing or missing/extra position in ascending index order.','Do not mutate inputs.'],['Equal and empty sequences.','Mismatch, missing transaction, extra transaction.','Input lists remain unchanged.'],'Iterate to max(len(expected),len(actual)), using None for absent entries; append records whenever values or existence differ.'),
executable('py-coverage','Functional coverage bin accounting','Design Verification','python','Count coverage from named bins instead of inventing a percentage from raw sample count.','def covered_bins(samples, bins):\n    # Return names whose inclusive [low, high] range has a sample.\n    return set()\n',['bins maps a name to (low, high), inclusive.','Return a set of covered names.','Empty bins and empty samples return an empty set.'],['Boundary values and repeated samples.','Overlapping bins can both be covered.'],'For each named range, mark it covered if any sample is between both inclusive endpoints.'),
executable('py-uart','Decode and validate an 8N1 frame','Advanced Applications','python','Decode a sampled ten-bit UART frame and reject malformed framing.','def decode_frame(bits):\n    # Validate start, stop and eight data bits.\n    return 0\n',['Exactly 10 integer bits, each 0 or 1.','Start=0, stop=1, eight data bits LSB-first.','Raise ValueError for invalid input.'],['All 256 valid bytes.','Wrong length, invalid bit, bad start/stop.'],'Validate framing before reconstructing sum(bits[i+1] << i for i in range(8)).'),
executable('py-timeout','Bounded handshake polling','Programming','python','Model a bounded ready wait and report a timeout explicitly.','def first_ready(samples, max_cycles):\n    # Return the first ready cycle, zero-based.\n    raise TimeoutError()\n',['max_cycles must be a positive integer; otherwise raise ValueError.','Inspect at most the first max_cycles supplied samples.','Return the first index with a truthy sample; otherwise raise TimeoutError.'],['Ready at cycle 0 and at the last allowed cycle.','Ready just beyond the limit must time out.','Invalid limits and empty input.'],'Validate the bound first, then enumerate the bounded slice; raise TimeoutError only after all allowed samples were examined.'),
executable('py-mask','Register writes with byte strobes','Advanced Applications','python','Update a 32-bit register using independent byte write enables.','def merge_write(old, data, strobe):\n    # Four strobe bits control four bytes.\n    return old\n',['Only low 32 bits of old/data and low four strobe bits matter.','Strobe bit i replaces byte i with data byte i.','Unselected bytes retain old values.'],['Zero/all strobes and every single-byte strobe.','All 16 masks and high-bit truncation.'],'For each selected byte, clear its 0xff mask in old and insert the corresponding data bits; mask the final result to 32 bits.')
];

const scenarioSpecs:[string,Track,string,string,string[],number,string][]=[
['overflow-vs-carry','Foundation','Signed overflow without carry','A 4-bit signed adder produces 1000 from 0111+0001. Which diagnosis is correct?',['Signed overflow occurred even though carry-out is zero','The result proves no overflow','The output is +8 in 4-bit signed form'],0,'Both operands are positive but the result has a negative sign.'],
['mux-unknown','Foundation','Unknown select in a mux','Simulation shows X on a mux select. What is the useful engineering response?',['Investigate initialization/reset and define four-state expectations','Replace every X with zero in reports','Ignore the transition because hardware is binary'],0,'Unknowns can reveal missing reset or uncontrolled inputs; the model must be interpreted deliberately.'],
['decoder-onehot','Foundation','A decoder asserts two bits','A decoder occasionally asserts two outputs for one address. Which property should catch it?',['One-hot output when enabled, zero when disabled','Only output bus width','Only whether any output ever becomes 1'],0,'The contract includes mutual exclusion, not merely activity.'],
['counter-wrap','RTL Design','Counter fails only at rollover','A counter passes the first ten increments but fails near its maximum. Which directed test is most useful?',['Maximum−1 → maximum → zero','Only reset at time zero','A longer idle interval'],0,'Boundary transitions isolate rollover behavior.'],
['blocking-pipeline','RTL Design','A simulated pipeline collapses','Two clocked assignments use blocking assignment and a downstream register sees the new input too early. Which change matches normal register semantics?',['Use nonblocking updates and check cycle latency','Add arbitrary testbench delays only','Delete the downstream checker'],0,'Clocked state should update simultaneously according to the intended pipeline.'],
['reset-middle','RTL Design','Reset during a transaction','A FSM is tested only with reset at startup. What important gap remains?',['Reset from each intermediate state and recovery','The editor color scheme','The number of source comments'],0,'Startup reset does not exercise state-dependent recovery.'],
['enable-hold','RTL Design','Disabled register changes','A register follows d while en=0. What contract is violated?',['State must hold while disabled','Output must always follow d','Reset must be asynchronous'],0,'The enable gates state capture, not input changes.'],
['fsm-overlap','RTL Design','A second sequence is missed','The stream 1011011 produces one pulse instead of two. Which likely fault fits?',['Match transition discards the valid suffix 1','The alphabet needs more than two symbols','The test should count only non-overlapping matches'],0,'Returning to empty loses the start of the overlapping match.'],
['width-truncation','RTL Design','A sum loses its carry','An 8-bit output receives the sum of two bytes. How should carry be checked if required?',['Use an explicitly widened result/interface','Assume an output bit appears automatically','Mark overflow tests as excluded'],0,'The interface must preserve the extra bit if the specification requires it.'],
['stale-log','Programming','A stale PASS file','Compilation fails but yesterday’s PASS log remains. How should the regression behave?',['Report compile failure and avoid interpreting stale results','Read the old PASS as current success','Increase coverage based on the old file'],0,'Artifacts need run identity and execution status.'],
['mutable-scoreboard','Programming','Scoreboards share transactions','Two Python scoreboard objects unexpectedly share expected items. What is a likely cause?',['A mutable class-level list used as instance data','A missing browser refresh','The simulator runs too slowly'],0,'Each instance should own its mutable queue unless sharing is intentional.'],
['parser-substring','Programming','A misleading PASS substring','A line says “FAIL test_expected_PASS”. Which parse is correct?',['One FAIL record','One PASS record','Both PASS and FAIL'],0,'Parse the defined token structure rather than substring occurrences.'],
['timeout-boundary','Programming','Ready arrives one cycle late','A wait permits cycles 0–9 and ready appears at cycle 10. The result should be…',['Timeout','Pass','A negative cycle index'],0,'The timeout boundary is part of the interface contract.'],
['seed-repro','Programming','A random bug cannot be reproduced','Which missing artifact most directly blocks reproducing a random stimulus sequence?',['The random seed and generator/tool context','The project banner','The CV template'],0,'Retain seed plus implementation context and failing transactions.'],
['signed-cpp','Programming','C++ model disagrees at the boundary','An RTL unsigned counter wraps but the C++ reference uses overflowing signed int. What should change?',['Use explicit unsigned width/masking','Trust signed overflow as modular','Remove the boundary test'],0,'Signed C++ overflow cannot safely model modular hardware arithmetic.'],
['vacuous-pass','Design Verification','An assertion never triggers','req |=> grant passes while req is always zero. What evidence is missing?',['Antecedent activation coverage','A larger PASS font','A shorter assertion name'],0,'Implication success can be vacuous when no request occurs.'],
['coverage-without-check','Design Verification','Coverage reaches 100% with wrong data','All functional bins hit, but the scoreboard reports corrupted outputs. Which conclusion is valid?',['Scenarios were exercised but correctness failed','The design passed because coverage wins','The scoreboard should be disabled'],0,'Coverage and correctness are different dimensions.'],
['requested-vs-accepted','Design Verification','A scoreboard drifts under backpressure','The reference queue enqueues every requested write. What should it track?',['Only accepted writes according to the handshake','Every clock edge','Only the first transfer'],0,'Rejected requests do not alter the DUT’s stored transaction sequence.'],
['missing-last-transaction','Design Verification','The test ends too early','All observed values match, but one expected item remains queued. Should this pass?',['No, the missing transaction must fail completion','Yes, observed values were correct','Only if code compiled'],0,'End-of-test must check pending expectations as well as mismatches.'],
['reset-scoreboard','Design Verification','A reset creates false mismatches','The DUT flushes pending transactions at reset. What must the reference model do?',['Apply the documented flush policy at reset','Keep all pending transactions unconditionally','Invent replacement outputs'],0,'Reference reset behavior must match the specification.'],
['coverage-exclusion','Design Verification','An unreachable coverage bin','A bin is unhit after many seeds. What is the next step?',['Review legality/reachability and justify any exclusion','Delete it to improve the percentage','Declare the next sample covered'],0,'Coverage closure requires traceable technical decisions.'],
['monitor-race','Design Verification','Monitor results depend on process order','The testbench drives and samples at the same edge without a timing policy. What is the likely issue?',['A scheduler race','Guaranteed RTL failure','An incompatible Git branch'],0,'Define clocking/sampling regions before judging the DUT.'],
['uart-stop','Advanced Applications','UART corrupt stop bit','A frame has correct data but stop=0. What should a framing-aware checker do?',['Flag a framing error','Always accept the byte','Reverse the data bits'],0,'Framing is part of the protocol, independently of data value.'],
['fifo-full-both','Advanced Applications','FIFO full with simultaneous requests','A test assumes write acceptance at full when read is also high. What must be checked first?',['The exact simultaneous-operation acceptance policy','The source filename','The project start date'],0,'Different interfaces legitimately define different full-boundary behavior.'],
['apb-wait-stability','Advanced Applications','APB address changes during a wait','PSEL and PENABLE remain high, PREADY is low, but PADDR changes. This is…',['A stability violation for the pending transfer','A completed new transfer','Always permitted by APB'],0,'Address/control stay associated with the current access until completion.'],
['axi-independent','Advanced Applications','AXI channels are treated as one','A checker requires write address and write data handshakes in the same cycle. What assumption should be reviewed?',['Independent AXI channel handshakes','The use of unsigned data','Whether documentation exists'],0,'AXI channel independence is fundamental to backpressure behavior.'],
['riscv-x0','Advanced Applications','RISC-V x0 changes after ADD','An instruction writes a nonzero value into architectural x0. The reference checker should…',['Fail: x0 must read zero','Accept any arithmetic result','Ignore all destination registers'],0,'Architectural x0 is hardwired to zero.'],
['cdc-grey','Advanced Applications','A synchronous FIFO test is reused for CDC','Passing one-clock queue tests proves which additional asynchronous property?',['None by itself; CDC/reset analysis remains needed','All metastability risks are eliminated','Both clock domains share an edge'],0,'Functional queue checks do not establish crossing safety.'],
['portfolio-evidence','Design Verification','A CV claims unmeasured coverage','A project has no coverage report but its CV says 100% functional coverage. The correct action is…',['Remove or qualify the claim until reproducible evidence exists','Keep the number because tests passed','Use code coverage as an identical substitute'],0,'Claims must match the actual metric, report and verification scope.']
];
const scenarios:Exercise[]=scenarioSpecs.map(([id,track,title,question,options,answer,explanation])=>({id,title,track,difficulty:track==='Advanced Applications'?'Advanced':'Intermediate',kind:'Debugging',minutes:15,description:`Investigate a realistic engineering failure: ${title.toLowerCase()}. Identify the root-cause hypothesis and the evidence needed to verify the fix.`,objectives:['Separate symptoms from causes','Choose a check that follows the specification'],specs:['Choose the technically justified diagnosis.','Explain the expected failing trace in Personal notes before reviewing the answer.'],tests:['Scenario diagnosis is scored against the documented rationale.'],hints:['State the interface contract before considering the observed symptom.','Choose the answer that produces reproducible evidence.'],solution:explanation,language:'systemverilog',starter:'',quiz:[q(question,options,answer,explanation)]}));

export function buildCurriculum(baseLessons:Lesson[],baseExercises:Exercise[]){
 const checkpoints:Exercise[]=topics.map(t=>{const l=baseLessons.find(l=>l.id===t.id)!;return {id:`checkpoint-${t.id}`,title:`Checkpoint: ${l.title}`,track:l.track,difficulty:l.track==='Advanced Applications'?'Advanced':l.track==='Foundation'?'Beginner':'Intermediate',kind:'Theory',minutes:20,description:`Assess the core decisions behind ${l.title.toLowerCase()}. This knowledge checkpoint is separate from practical test evidence.`,objectives:['Explain the concept and its limits','Apply the concept to a concrete engineering decision'],specs:['Answer every question. All answers must be correct.','Reading completion alone does not pass this checkpoint.'],tests:t.questions.map((x,i)=>`${i+1}. ${x.question}`),hints:['Work through the lesson’s example first.','Explain why the rejected alternatives violate the contract.'],solution:t.questions.map(x=>x.explanation).join(' '),language:'systemverilog',starter:'',quiz:t.questions} as Exercise});
 const lessons=baseLessons.map(l=>{const t=topics.find(t=>t.id===l.id)!;const assessmentIds=[`checkpoint-${l.id}`,...(t.practice?[t.practice]:[])];return {...l,minutes:30,exerciseId:`checkpoint-${l.id}`,assessmentIds,body:l.body+`\n\n## Worked engineering example\n${t.example}\n\n## Common failure to investigate\n${t.pitfall}\n\n## Your evidence task\n${t.deliverable}\n\n### A useful review sequence\n1. Write the contract in your own words, including widths, timing and legal inputs.\n2. Work one normal case by hand and then one boundary or invalid case.\n3. Predict which checker would fail for the mistake above.\n4. Save your explanation, actual commands and observed results in the Knowledge Vault or linked project.\n\n## Completion criteria\nPass **Checkpoint: ${l.title}**${t.practice?' and the linked executable exercise **'+t.practice+'**':''}, then mark this lesson as read. This verifies the listed learning outcomes; it is not a claim of professional-level mastery of the entire field.\n\n## Reflect before moving on\nWhat assumption would make your result invalid? Which corner case remains untested? State both in a short English engineering note.\n`}});
 const exercises=[...baseExercises,...checkpoints,...codingExercises,...scenarios].map(e=>({...e,quiz:e.quiz?.map((question,index)=>{const shift=([...e.id].reduce((n,c)=>n+c.charCodeAt(0),index))%question.options.length;return {...question,options:[...question.options.slice(shift),...question.options.slice(0,shift)],answer:(question.answer-shift+question.options.length)%question.options.length}})}));
 return {lessons,exercises};
}
